import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String number = br.readLine().trim();
        int m = Integer.parseInt(br.readLine().trim());

        int[] keypad = new int[26];
        String[] groups = {"abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        for (int i = 0; i < groups.length; i++) {
            for (char c : groups[i].toCharArray()) {
                keypad[c - 'a'] = i + 2;
            }
        }

        int count = 0;
        for (int i = 0; i < m; i++) {
            String word = br.readLine().trim();
            if (word.length() != number.length()) {
                continue;
            }

            boolean matches = true;
            for (int j = 0; j < word.length(); j++) {
                if (keypad[word.charAt(j) - 'a'] != number.charAt(j) - '0') {
                    matches = false;
                    break;
                }
            }
            if (matches) {
                count++;
            }
        }

        System.out.println(count);
    }
}
